css:
.uv-nlp {
  --c1: #0f766e;
  --c2: #ccfbf1;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-nlp {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  width: 13em;
  height: 17em;
}

.uv-nlp .tg {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  display: flex;
  align-items: center;
  gap: .45em;
  padding: .55em .8em;
  border-radius: 2em;
  font-weight: 700;
  background: color-mix(in srgb,var(--fg) 2%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 8%,transparent),0 1.4em 2.8em -1.4em rgba(0,0,0,.45);
}

.uv-nlp .tg>svg {
  width: 1.15em;
  height: 1.15em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uv-nlp .tg>svg:last-child {
  width: .95em;
  height: .95em;
  transition: transform calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-nlp.open .tg>svg:last-child {
  transform: rotate(180deg);
}

.uv-nlp .cd {
  display: inline-block;
  min-width: 1.6em;
  perspective: 6em;
}

.uv-nlp .cd b {
  display: inline-block;
}

.uv-nlp .cd b.flip {
  animation: uv-nlp calc(0.45s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uv-nlp .tg:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uv-nlp ul {
  position: absolute;
  left: 0;
  top: 3em;
  width: 12em;
  margin: 0;
  padding: .35em;
  list-style: none;
  border-radius: 1em;
  background: color-mix(in srgb,var(--fg) 2%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 8%,transparent),0 1.4em 2.8em -1.4em rgba(0,0,0,.45);
  opacity: 0;
  visibility: hidden;
  transform: translateY(-.4em) scale(.96);
  transform-origin: 20% 0;
  transition: all calc(0.25s / var(--k)) cubic-bezier(.22,1,.36,1);
  outline: 0;
}

.uv-nlp.open ul {
  opacity: 1;
  visibility: visible;
  transform: none;
}

.uv-nlp li {
  display: flex;
  align-items: center;
  gap: .6em;
  padding: .5em .6em;
  border-radius: .6em;
  font-size: .9em;
  cursor: pointer;
  outline: 0;
  transition: background calc(0.15s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-nlp li:hover,.uv-nlp li:focus {
  background: color-mix(in srgb,var(--fg) 6%,transparent);
}

.uv-nlp li:focus-visible {
  box-shadow: inset 0 0 0 2px var(--c1);
}

.uv-nlp .fl {
  font-size: 1.15em;
}

.uv-nlp .ck {
  display: grid;
  margin-left: auto;
  color: var(--c1);
  opacity: 0;
  transform: scale(.5);
  transition: all calc(0.3s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uv-nlp .ck svg {
  width: 1em;
  height: 1em;
}

.uv-nlp li[aria-selected="true"] {
  font-weight: 700;
  background: var(--c2);
  color: var(--c1);
}

.uv-nlp li[aria-selected="true"] .ck {
  opacity: 1;
  transform: none;
}

@keyframes uv-nlp {
  0% {
    transform: rotateX(90deg);
    opacity: 0;
  }
  100% {
    transform: none;
    opacity: 1;
  }
}

