css:
.uv-nft {
  --c1: #2563eb;
  --c2: #dbeafe;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-nft {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  width: 15em;
  padding: .5em;
  border-radius: 1.1em;
  background: color-mix(in srgb,var(--fg) 2%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 8%,transparent),0 1.4em 2.8em -1.4em rgba(0,0,0,.45);
  font-size: calc(var(--s) * .95);
}

.uv-nft summary,.uv-nft a {
  display: flex;
  align-items: center;
  gap: .4em;
  padding: .38em .5em;
  border-radius: .5em;
  color: var(--fg);
  text-decoration: none;
  cursor: pointer;
  list-style: none;
  outline: 0;
  transition: background calc(0.15s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-nft summary::-webkit-details-marker {
  display: none;
}

.uv-nft summary>svg:first-child {
  width: .85em;
  height: .85em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
  transition: transform calc(0.3s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uv-nft details[open]>summary>svg:first-child {
  transform: rotate(90deg);
}

.uv-nft summary>svg:nth-child(2) {
  width: 1.05em;
  height: 1.05em;
  color: var(--c1);
  fill: color-mix(in srgb,var(--c1) 18%,transparent);
}

.uv-nft a svg {
  width: 1.05em;
  height: 1.05em;
  margin-left: 1.25em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uv-nft summary:hover,.uv-nft a:hover {
  background: color-mix(in srgb,var(--fg) 6%,transparent);
}

.uv-nft summary:focus-visible,.uv-nft a:focus-visible {
  box-shadow: inset 0 0 0 2px var(--c1);
}

.uv-nft a[aria-current] {
  font-weight: 650;
  color: var(--c1);
  background: var(--c2);
}

.uv-nft a[aria-current] svg {
  color: var(--c1);
}

.uv-nft .ch {
  position: relative;
  margin-left: .9em;
  padding-left: .35em;
}

.uv-nft .ch::before {
  content: "";
  position: absolute;
  left: 0;
  top: .2em;
  bottom: .2em;
  width: 1px;
  background: color-mix(in srgb,var(--fg) 12%,transparent);
}

.uv-nft details[open]>.ch {
  animation: uv-nft calc(0.3s / var(--k)) cubic-bezier(.22,1,.36,1);
}

@keyframes uv-nft {
  from {
    opacity: 0;
    transform: translateY(-.4em);
  }
}

@media (prefers-reduced-motion:reduce) {
  .uv-nft,.uv-nft *,.uv-nft *::before,.uv-nft *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

