css:
.uv-nbr {
  --c1: #e5e7eb;
  --c2: #3b82f6;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-nbr {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  width: 22em;
  border-radius: 1em;
  overflow: hidden;
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 10%,transparent),0 1.2em 2.4em -1.4em rgba(0,0,0,.45);
}

.uv-nbr .st {
  display: flex;
  align-items: flex-end;
  gap: .1em;
  height: 2.6em;
  padding: 0 .4em;
  background: color-mix(in srgb,var(--c1) 70%,var(--bg));
}

.uv-nbr .tb {
  position: relative;
  display: flex;
  align-items: center;
  flex: 0 1 7.5em;
  min-width: 0;
  height: 2.2em;
  padding: 0 .3em 0 .6em;
  border-radius: .7em .7em 0 0;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
  transition: flex-basis calc(0.3s / var(--k)) cubic-bezier(.22,1,.36,1),background calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1),opacity calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-nbr .tb:hover {
  background: color-mix(in srgb,var(--bg) 45%,transparent);
}

.uv-nbr .tb.on {
  color: var(--fg);
  background: var(--bg);
}

.uv-nbr .tb.on::before,.uv-nbr .tb.on::after {
  content: "";
  position: absolute;
  bottom: 0;
  width: .7em;
  height: .7em;
  background: radial-gradient(circle at 0 0,transparent .7em,var(--bg) .72em);
}

.uv-nbr .tb.on::before {
  left: -.7em;
  background: radial-gradient(circle at 0 0,transparent .7em,var(--bg) .72em);
  transform: scaleX(-1);
}

.uv-nbr .tb.on::after {
  right: -.7em;
}

.uv-nbr .tb.gone {
  flex-basis: 0;
  opacity: 0;
  padding: 0;
}

.uv-nbr .tb.new {
  animation: uv-nbr calc(0.35s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uv-nbr .lb {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  display: flex;
  align-items: center;
  gap: .45em;
  flex: 1;
  min-width: 0;
  height: 100%;
  font-size: .78em;
  font-weight: 600;
  color: inherit;
}

.uv-nbr .lb i {
  flex: none;
  width: .9em;
  height: .9em;
  border-radius: .25em;
  background: var(--f);
}

.uv-nbr .lb span {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.uv-nbr .x {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  display: grid;
  place-items: center;
  flex: none;
  width: 1.4em;
  height: 1.4em;
  border-radius: 50%;
  color: inherit;
  opacity: .7;
}

.uv-nbr .x:hover {
  background: color-mix(in srgb,var(--fg) 10%,transparent);
  opacity: 1;
}

.uv-nbr .x svg {
  width: .8em;
  height: .8em;
}

.uv-nbr .ad {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  display: grid;
  place-items: center;
  flex: none;
  width: 1.8em;
  height: 1.8em;
  margin: 0 0 .2em .3em;
  border-radius: 50%;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uv-nbr .ad:hover {
  background: color-mix(in srgb,var(--bg) 50%,transparent);
}

.uv-nbr .ad svg {
  width: 1em;
  height: 1em;
}

.uv-nbr button:focus-visible {
  outline: 2px solid var(--c2);
  outline-offset: -2px;
}

.uv-nbr .tl {
  padding: .5em .6em;
  background: var(--bg);
}

.uv-nbr .ur {
  display: flex;
  align-items: center;
  gap: .4em;
  padding: .45em .8em;
  border-radius: 2em;
  font-size: .8em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
  background: color-mix(in srgb,var(--fg) 6%,transparent);
}

.uv-nbr .ur svg {
  width: 1em;
  height: 1em;
}

@keyframes uv-nbr {
  from {
    flex-basis: 0;
    opacity: 0;
  }
}

