// Interacción en JavaScript del DOM: la misma que en la pestaña JS.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
function setup(el: any) {
  const st=el.querySelector(".st"),ad=st.querySelector(".ad"),u=el.querySelector(".u");const H={Correo:"correo.app",Calendario:"calendario.app"};
const act=t=>{st.querySelectorAll(".tb").forEach(x=>{x.classList.toggle("on",x===t);x.querySelector(".lb").setAttribute("aria-selected",String(x===t))});const n=t.querySelector(".lb span").textContent;u.textContent=H[n]||n.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/\s+/g,"-")+".app"};
const wire=t=>{t.querySelector(".lb").addEventListener("click",()=>act(t));t.querySelector(".x").addEventListener("click",e=>{e.stopPropagation();const tabs=[...st.querySelectorAll(".tb:not(.gone)")];if(tabs.length<2)return;const i=tabs.indexOf(t);t.classList.add("gone");if(t.classList.contains("on"))act(tabs[i+1]||tabs[i-1]);setTimeout(()=>t.remove(),300)})};
st.querySelectorAll(".tb").forEach(wire);
ad.addEventListener("click",()=>{if(st.querySelectorAll(".tb:not(.gone)").length>=5)return;const t=st.querySelector(".tb").cloneNode(true);t.className="tb new";t.style.setProperty("--f","#22c55e");t.querySelector(".lb span").textContent=ad.getAttribute("aria-label");t.querySelector(".x").setAttribute("aria-label","Cerrar");st.insertBefore(t,ad);wire(t);act(t)})
}

