css:
.uvq12-gg {
  --c1: #f59e0b;
  --c2: #1c1917;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq12-gg {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  width: 19em;
  padding: .9em .9em .7em;
  border-radius: 1.4em;
  color: #e7e5e4;
  background: linear-gradient(180deg,color-mix(in srgb,var(--c2) 80%,#fff 8%),var(--c2));
  box-shadow: inset 0 1px 0 rgba(255,255,255,.1),0 1.2em 2.4em -1.2em rgba(0,0,0,.6);
  --i: 0;
}

.uvq12-gg .sc {
  position: relative;
  height: 3.7em;
  margin-bottom: .6em;
  border-radius: .7em;
  overflow: hidden;
  background: #0c0a09;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.07),inset 0 .4em 1em rgba(0,0,0,.8);
}

.uvq12-gg .sc::after {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(0deg,rgba(255,255,255,.035) 0 1px,transparent 1px 3px);
  pointer-events: none;
}

.uvq12-gg .pn {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: .2em;
  padding: 0 1em;
  animation: uvq12-gg calc(0.45s / var(--k)) steps(1,end);
}

.uvq12-gg .pn[hidden] {
  display: none;
}

.uvq12-gg .pn b {
  font-size: 1.15em;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--c1);
  text-shadow: 0 0 .7em color-mix(in srgb,var(--c1) 60%,transparent);
}

.uvq12-gg .pn span {
  font-size: .74em;
  color: color-mix(in srgb,var(--c1) 55%,#a8a29e);
}

.uvq12-gg .gt {
  position: relative;
  display: grid;
  grid-template-columns: repeat(4,1fr);
  height: 4.3em;
  touch-action: pan-y;
}

.uvq12-gg .sl {
  position: absolute;
  left: calc(12.5% - .4em);
  right: calc(12.5% - .4em);
  top: 2.55em;
  height: .75em;
  border-radius: 1em;
  background: #050505;
  box-shadow: inset 0 .15em .3em rgba(0,0,0,.9),0 1px 0 rgba(255,255,255,.1);
}

.uvq12-gg .kn {
  position: absolute;
  z-index: 2;
  top: 2.92em;
  left: calc(12.5% + var(--i) * 25%);
  width: 2.2em;
  height: 2.2em;
  margin: -1.1em 0 0 -1.1em;
  border-radius: 50%;
  pointer-events: none;
  background: radial-gradient(circle at 35% 30%,#fafafa,#a1a1aa 45%,#3f3f46 80%);
  box-shadow: 0 .45em .7em rgba(0,0,0,.6),0 0 0 .16em #111,0 0 0 .3em color-mix(in srgb,var(--c1) 70%,transparent),0 0 1.1em color-mix(in srgb,var(--c1) 45%,transparent);
  transition: left calc(0.55s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq12-gg [role="tab"] {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: relative;
  z-index: 1;
  display: flex;
  justify-content: center;
  height: 100%;
  padding-top: .25em;
  border-radius: .6em;
}

.uvq12-gg [role="tab"] b {
  font-size: 1.05em;
  font-weight: 800;
  color: #57534e;
  transition: color calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1),text-shadow calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq12-gg [role="tab"]:hover b {
  color: #a8a29e;
}

.uvq12-gg [role="tab"][aria-selected="true"] b {
  color: var(--c1);
  text-shadow: 0 0 .55em var(--c1);
}

.uvq12-gg [role="tab"]:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: -2px;
}

.uvq12-gg [role="tab"]:active b {
  transform: translateY(1px);
}

.uvq12-gg>small {
  display: block;
  margin-top: .35em;
  text-align: center;
