css:
.uvq12-bt {
  --c1: #1e3a8a;
  --c2: #fffdf5;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq12-bt {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  width: 20.5em;
  height: 15em;
}

.uvq12-bt .pg {
  position: absolute;
  z-index: 1;
  left: 0;
  top: 0;
  bottom: 0;
  right: 2.4em;
  border-radius: .35em .6em .6em .35em;
  overflow: hidden;
  color: var(--c1);
  background: linear-gradient(90deg,transparent 2.6em,#f8717199 2.6em calc(2.6em + 1px),transparent calc(2.6em + 1px)),repeating-linear-gradient(180deg,transparent 0 calc(1.5em - 1px),#93c5fd88 calc(1.5em - 1px) 1.5em) 0 .55em,var(--c2);
  box-shadow: .2em .2em 0 -.05em #e7e5e4,.35em .35em 0 -.1em #d6d3d1,0 1.2em 2em -1em rgba(0,0,0,.45);
}

.uvq12-bt .ho {
  position: absolute;
  left: .75em;
  top: 0;
  bottom: 0;
  width: 1em;
  background: radial-gradient(circle at 50% 50%,var(--bg) .3em,#d6d3d1 .32em .4em,transparent .42em) 0 .9em/1em 4.2em repeat-y;
}

.uvq12-bt .pn {
  position: absolute;
  inset: .55em 1em 0 3.2em;
  animation: uvq12-bt calc(0.5s / var(--k)) cubic-bezier(.22,1,.36,1);
  transform-origin: 0 50%;
}

.uvq12-bt .pn[hidden] {
  display: none;
}

.uvq12-bt h4 {
  display: inline-block;
  margin: 0;
  font: 700 1.25em/1.2 "Segoe Print","Bradley Hand","Chalkboard SE","Comic Sans MS",cursive;
  padding: 0 .2em;
  background: linear-gradient(transparent 55%,var(--t) 55% 90%,transparent 90%);
}

.uvq12-bt ul {
  margin: .15em 0 0;
  padding: 0;
  list-style: none;
}

.uvq12-bt li {
  display: flex;
  align-items: center;
  gap: .5em;
  height: 1.5em;
  font: 500 .95em/1 "Segoe Print","Bradley Hand","Chalkboard SE","Comic Sans MS",cursive;
}

.uvq12-bt li::before {
  content: "";
  flex: none;
  width: .7em;
  height: .7em;
  border: 1.5px solid currentColor;
  border-radius: .15em;
  opacity: .7;
}

.uvq12-bt .tbs {
  position: absolute;
  right: 0;
  top: .6em;
  display: flex;
  flex-direction: column;
  gap: .25em;
}

.uvq12-bt [role="tab"] {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: relative;
  display: flex;
  justify-content: flex-end;
  width: 3.1em;
  height: 3.35em;
  padding-right: .55em;
  border-radius: 0 .55em .55em 0;
  color: #292524;
  background: var(--t);
  box-shadow: inset -.15em 0 0 rgba(0,0,0,.06),0 .3em .5em -.3em rgba(0,0,0,.45);
  transform: translateX(-.35em);
  transition: transform calc(0.35s / var(--k)) cubic-bezier(.34,1.56,.64,1),filter calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq12-bt [role="tab"] span {
  writing-mode: vertical-rl;
  margin: auto 0;
  font-size: .56em;
  font-weight: 800;
  letter-spacing: .05em;
  text-transform: uppercase;
}

.uvq12-bt [role="tab"]:hover {
  transform: translateX(-.1em);
  filter: brightness(1.04);
}

.uvq12-bt [role="tab"][aria-selected="true"] {
  z-index: 2;
  transform: translateX(.2em);
}

.uvq12-bt [role="tab"]:active {
  transform: translateX(0) scale(.97);
}

.uvq12-bt [role="tab"]:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 2px;
}

@keyframes uvq12-bt {
  from {
    opacity: 0;
    transform: perspective(40em) rotateY(-28deg);
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq12-bt,.uvq12-bt *,.uvq12-bt *::before,.uvq12-bt *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

