  width: 1em;
  height: 1em;
}

.uvq12-tp .pv:active,.uvq12-tp .nx:active {
  transform: scale(.88);
}

.uvq12-tp .pv:disabled,.uvq12-tp .nx:disabled {
  opacity: .35;
  cursor: default;
}

.uvq12-tp button:focus-visible,.uvq12-tp .vw:focus-visible {
  outline: 2px solid var(--c2);
  outline-offset: 3px;
}

.uvq12-tp .vw {
  position: relative;
