  transform: translateX(calc(5.5em - (var(--p) - 1) * 3em));
  transition: transform calc(0.55s / var(--k)) cubic-bezier(.22,1,.36,1);
  will-change: transform;
}

.uvq12-tp.drag .tp {
  transition: none;
}

.uvq12-tp .tp span {
  position: relative;
  flex: none;
