document.querySelectorAll(".uvq12-tp").forEach(el => {
  const vw=el.querySelector(".vw"),tp=el.querySelector(".tp"),pn=el.querySelector(".pn"),pv=el.querySelector(".pv"),nx=el.querySelector(".nx"),sp=[...tp.children],N=sp.length;let p=7,dn=null;
const go=k=>{p=Math.max(1,Math.min(N,Math.round(k)));el.classList.remove("drag");el.style.setProperty("--p",p);pn.textContent=p;vw.setAttribute("aria-valuenow",p);pv.disabled=p===1;nx.disabled=p===N;sp.forEach((s,j)=>s.classList.toggle("on",j===p-1))};
const unit=()=>parseFloat(getComputedStyle(tp).fontSize)*3*(vw.getBoundingClientRect().width/vw.offsetWidth);
vw.addEventListener("pointerdown",e=>{dn={x:e.clientX,p,u:unit(),t:e.timeStamp,v:0,lx:e.clientX,m:false,f:p}});
vw.addEventListener("pointermove",e=>{if(!dn)return;const dx=e.clientX-dn.x;if(!dn.m&&Math.abs(dx)>4){dn.m=true;el.classList.add("drag");vw.setPointerCapture(e.pointerId)}if(!dn.m)return;const dt=Math.max(1,e.timeStamp-dn.t);dn.v=(e.clientX-dn.lx)/dt;dn.lx=e.clientX;dn.t=e.timeStamp;let f=dn.p-dx/dn.u;if(f<1)f=1-(1-f)*.3;if(f>N)f=N+(f-N)*.3;dn.f=f;el.style.setProperty("--p",f)});
vw.addEventListener("pointerup",e=>{if(!dn)return;const d=dn;dn=null;if(d.m)go(d.f-d.v*200/d.u);else{const s=e.target.closest(".tp span");if(s)go(sp.indexOf(s)+1)}});
vw.addEventListener("pointercancel",()=>{if(dn){dn=null;go(p)}});
vw.addEventListener("keydown",e=>{const m={ArrowLeft:-1,ArrowDown:-1,ArrowRight:1,ArrowUp:1,PageDown:-5,PageUp:5}[e.key];if(m){e.preventDefault();go(p+m)}if(e.key==="Home"){e.preventDefault();go(1)}if(e.key==="End"){e.preventDefault();go(N)}});
pv.addEventListener("click",()=>go(p-1));nx.addEventListener("click",()=>go(p+1));go(p)
});

