.uvq12-el {
  --c1: #f59e0b;
  --c2: #d4d4d8;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq12-el {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  width: 13em;
  padding: 1em;
  border-radius: .9em;
  color: #27272a;
  background: repeating-linear-gradient(0deg,rgba(255,255,255,.1) 0 1px,transparent 1px 3px),linear-gradient(90deg,color-mix(in srgb,var(--c2) 80%,#71717a),color-mix(in srgb,var(--c2) 85%,#fff) 35%,var(--c2) 60%,color-mix(in srgb,var(--c2) 85%,#52525b));
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.4),0 1.2em 2.4em -1.2em rgba(0,0,0,.55);
}

.uvq12-el .ds {
  position: relative;
  display: flex;
  align-items: center;
  gap: .6em;
  height: 3.6em;
  padding: 0 .8em;
  margin-bottom: .9em;
  border-radius: .5em;
  background: #0a0a0a;
  box-shadow: inset 0 .2em .5em rgba(0,0,0,.8),0 1px 0 rgba(255,255,255,.5);
  overflow: hidden;
}

.uvq12-el .ds::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(circle,transparent 50%,rgba(10,10,10,.55) 75%) 0 0/.16em .16em;
  pointer-events: none;
}

.uvq12-el .dr {
  width: 1em;
  font-size: 1.2em;
  color: var(--c1);
  text-shadow: 0 0 .4em var(--c1);
}

.uvq12-el .dr.u::before {
  content: "▲";
  display: block;
  animation: uvq12-el-u calc(0.6s / var(--k)) linear infinite;
}

.uvq12-el .dr.d::before {
  content: "▼";
  display: block;
  animation: uvq12-el-d calc(0.6s / var(--k)) linear infinite;
}

.uvq12-el .fn {
  min-width: 1em;
  font: 800 2.2em/1 ui-monospace,"SF Mono",Menlo,Consolas,monospace;
  color: var(--c1);
  text-shadow: 0 0 .35em var(--c1);
}

.uvq12-el .lb {
  display: flex;
  flex-direction: column;
  min-width: 0;
  color: var(--c1);
  font-size: .72em;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .08em;
}

.uvq12-el .lb small {
  font-size: .75em;
  opacity: .6;
}

.uvq12-el .nm {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.uvq12-el.ding .ds {
  animation: uvq12-el calc(0.5s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq12-el ul {
  display: flex;
  flex-direction: column;
  gap: .45em;
  margin: 0;
  padding: 0;
  list-style: none;
}

.uvq12-el li button {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  display: flex;
  align-items: center;
  gap: .8em;
  width: 100%;
  padding: .2em;
  border-radius: 2em;
}

.uvq12-el .bt {
  display: grid;
  place-items: center;
  width: 2.4em;
  height: 2.4em;
  border-radius: 50%;
  font-weight: 800;
  color: #3f3f46;
  background: radial-gradient(circle at 40% 35%,#fafafa,#a1a1aa 70%,#71717a);
  box-shadow: 0 0 0 .2em #52525b,0 0 0 .26em rgba(255,255,255,.5),0 .25em .4em rgba(0,0,0,.4);
  transition: box-shadow calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1),transform calc(0.1s / var(--k)) cubic-bezier(.25,.1,.25,1),color calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq12-el .tx {
  font-size: .85em;
  font-weight: 700;
  letter-spacing: .02em;
  color: #3f3f46;
  text-shadow: 0 1px 0 rgba(255,255,255,.6);
}

.uvq12-el li button:hover .bt {
  transform: scale(1.04);
}

.uvq12-el li button:active .bt {
  transform: scale(.94);
  box-shadow: 0 0 0 .2em #52525b,0 0 0 .26em rgba(255,255,255,.5),0 .05em .1em rgba(0,0,0,.4);
}

.uvq12-el li button.on .bt {
  color: color-mix(in srgb,var(--c1) 70%,#000);
  box-shadow: 0 0 0 .2em var(--c1),0 0 0 .26em rgba(255,255,255,.5),0 0 1em var(--c1),0 .25em .4em rgba(0,0,0,.4);
}

.uvq12-el li button[aria-current] .tx {
  color: #000;
  text-decoration: underline;
  text-decoration-color: var(--c1);
  text-decoration-thickness: .15em;
  text-underline-offset: .25em;
}

.uvq12-el li button:focus-visible {
  outline: 2px solid #18181b;
  outline-offset: 2px;
}

@keyframes uvq12-el {
  30% {
    box-shadow: inset 0 .2em .5em rgba(0,0,0,.8),0 0 1.4em var(--c1);
  }
}

@keyframes uvq12-el-u {
  from {
    transform: translateY(.5em);
    opacity: 0;
  }
  50% {
    opacity: 1;
  }
  to {
    transform: translateY(-.5em);
    opacity: 0;
  }
}

@keyframes uvq12-el-d {
  from {
    transform: translateY(-.5em);
    opacity: 0;
  }
  50% {
    opacity: 1;
  }
  to {
    transform: translateY(.5em);
    opacity: 0;
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq12-el,.uvq12-el *,.uvq12-el *::before,.uvq12-el *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

