document.querySelectorAll(".uvq12-el").forEach(el => {
  const bs=[...el.querySelectorAll("li button")],fn=el.querySelector(".fn"),dr=el.querySelector(".dr"),nm=el.querySelector(".nm");let cur=0,to=0,tm=0;
const K=()=>parseFloat(getComputedStyle(el).getPropertyValue("--k"))||1;const btn=f=>bs.find(b=>+b.dataset.f===f);
const arrive=()=>{dr.className="dr";const b=btn(cur);b.classList.remove("on");bs.forEach(x=>{if(x===b)x.setAttribute("aria-current","true");else x.removeAttribute("aria-current")});nm.textContent=b.querySelector(".tx").textContent;el.classList.remove("ding");void el.offsetWidth;el.classList.add("ding")};
const step=()=>{if(cur===to){arrive();tm=0;return}cur+=to>cur?1:-1;fn.textContent=cur;tm=setTimeout(step,(cur===to?300:650)/K())};
const call=f=>{if(f===to&&tm)return;bs.forEach(b=>b.classList.toggle("on",+b.dataset.f===f&&f!==cur));to=f;if(f===cur&&!tm)return;dr.className="dr "+(f>cur?"u":"d");if(!tm)tm=setTimeout(step,400/K())};
bs.forEach((b,i)=>{b.addEventListener("click",()=>call(+b.dataset.f));b.addEventListener("keydown",e=>{const n=e.key==="ArrowDown"?i+1:e.key==="ArrowUp"?i-1:-1;if(n>=0&&n<bs.length){e.preventDefault();bs[n].focus()}})});
el.addEventListener("keydown",e=>{if(/^[0-4]$/.test(e.key)){e.preventDefault();const b=btn(+e.key);b.focus();call(+e.key)}});return()=>clearTimeout(tm)
});

