  /* fondo */
}

.uvq12-fb {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  width: 19.5em;
}

.uvq12-fb .bd {
  padding: .7em .8em .8em;
  border-radius: .8em;
  color: var(--c1);
  background: var(--c2);
