  height: 15em;
  min-width: 12em;
  max-width: 30em;
}

.uvq12-pp nav {
  position: relative;
  display: flex;
  align-items: center;
  gap: .3em;
  height: 3em;
  padding: 0 .35em 0 .9em;
  border-radius: 1em;
  background: color-mix(in srgb,var(--fg) 2%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 9%,transparent),0 1.4em 2.8em -1.4em rgba(0,0,0,.45);
}

.uvq12-pp ul {
  margin: 0;
  padding: 0;
  list-style: none;
}

.uvq12-pp .lg {
  display: flex;
  align-items: center;
  gap: .4em;
  flex: none;
  margin-right: .3em;
  font-weight: 800;
  letter-spacing: -.02em;
  color: var(--fg);
  text-decoration: none;
  border-radius: .4em;
}

.uvq12-pp .lg i {
  width: .8em;
  height: .8em;
  border-radius: .25em;
  background: var(--c1);
  transform: rotate(45deg);
}

