css:
.uvq12-kc {
  --c1: #f97316;
  --c2: #2a2826;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq12-kc {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  width: 21em;
  padding: 1em 1em .9em;
  border-radius: 1em;
  background: linear-gradient(180deg,color-mix(in srgb,var(--c2) 85%,#fff 10%),var(--c2));
  box-shadow: inset 0 1px 0 rgba(255,255,255,.12),inset 0 -.3em .6em rgba(0,0,0,.3),0 1.2em 2.4em -1.2em rgba(0,0,0,.6);
}

.uvq12-kc .ks {
  display: grid;
  grid-template-columns: repeat(4,1fr);
  gap: .45em;
  padding: .4em;
  border-radius: .6em;
  background: rgba(0,0,0,.35);
  box-shadow: inset 0 .2em .4em rgba(0,0,0,.5);
}

.uvq12-kc [role="tab"] {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  height: 4.4em;
  border-radius: .55em;
  outline: 0;
}

.uvq12-kc .cap {
  position: relative;
  display: block;
  height: 4em;
  border-radius: .55em;
  color: #44403c;
  background: linear-gradient(180deg,#d9d2c3,#b9b09c);
  box-shadow: 0 .35em 0 #857c6a,0 .45em .6em rgba(0,0,0,.4);
  transition: transform calc(0.08s / var(--k)) cubic-bezier(.25,.1,.25,1),box-shadow calc(0.08s / var(--k)) cubic-bezier(.25,.1,.25,1),background calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq12-kc .cap::before {
  content: "";
  position: absolute;
  inset: .28em .38em .62em;
  border-radius: .45em;
  background: linear-gradient(180deg,#f3eee4,#ddd5c4);
  box-shadow: inset 0 .1em .15em rgba(255,255,255,.8),inset 0 -.15em .3em rgba(0,0,0,.08);
}

.uvq12-kc .cap b,.uvq12-kc .cap span {
  position: absolute;
  left: .75em;
  font-weight: 800;
  text-transform: uppercase;
}

.uvq12-kc .cap b {
  top: .55em;
  font-size: .8em;
}

.uvq12-kc .cap span {
  bottom: 1.25em;
  max-width: calc(100% - 1.2em);
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: .52em;
  letter-spacing: .06em;
  white-space: nowrap;
}

.uvq12-kc .led {
  position: absolute;
  right: .65em;
  top: .65em;
  width: .35em;
  height: .35em;
  border-radius: 50%;
  background: rgba(0,0,0,.2);
}

.uvq12-kc [role="tab"]:hover .cap::before {
  background: linear-gradient(180deg,#f8f4ec,#e3dccd);
}

.uvq12-kc [role="tab"]:active .cap,.uvq12-kc .dn .cap {
  transform: translateY(.28em);
  box-shadow: 0 .07em 0 #857c6a,0 .12em .2em rgba(0,0,0,.4);
}

.uvq12-kc [aria-selected="true"] .cap {
  color: #fff;
  background: linear-gradient(180deg,color-mix(in srgb,var(--c1) 85%,#fff),color-mix(in srgb,var(--c1) 85%,#000));
  box-shadow: 0 .35em 0 color-mix(in srgb,var(--c1) 55%,#000),0 .45em .6em rgba(0,0,0,.4);
}

.uvq12-kc [aria-selected="true"] .cap::before {
  background: linear-gradient(180deg,color-mix(in srgb,var(--c1) 70%,#fff),var(--c1));
  box-shadow: inset 0 .1em .15em rgba(255,255,255,.45),inset 0 -.15em .3em rgba(0,0,0,.12);
}

.uvq12-kc [aria-selected="true"] .led {
  background: #bef264;
  box-shadow: 0 0 .4em #a3e635;
}

.uvq12-kc [role="tab"]:focus-visible .cap {
  outline: 2px solid #fafaf9;
  outline-offset: 2px;
}

.uvq12-kc .sc {
  margin-top: .8em;
  padding: .55em .8em;
  border-radius: .4em;
  background: #0c0f0a;
  box-shadow: inset 0 .15em .3em rgba(0,0,0,.6);
}

.uvq12-kc .pn {
  font-family: ui-monospace,"SF Mono",Menlo,Consolas,monospace;
  font-size: .78em;
  color: #bef264;
  text-shadow: 0 0 .4em rgba(190,242,100,.4);
  animation: uvq12-kc calc(0.35s / var(--k)) steps(6,end);
}

.uvq12-kc .pn::before {
