.uvq12-sh {
  --c1: #3fb950;
  --c2: #58a6ff;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq12-sh {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  width: 22em;
  border-radius: .8em;
  overflow: hidden;
  color: #c9d1d9;
  background: #0d1117;
  box-shadow: 0 0 0 1px rgba(255,255,255,.08),0 1.2em 2.4em -1.2em rgba(0,0,0,.6);
  font-family: ui-monospace,"SF Mono",Menlo,Consolas,monospace;
}

.uvq12-sh .tb {
  display: flex;
  align-items: center;
  gap: .4em;
  padding: .55em .8em;
  background: #161b22;
  border-bottom: 1px solid rgba(255,255,255,.06);
}

.uvq12-sh .tb i {
  width: .65em;
  height: .65em;
  border-radius: 50%;
  background: #ff5f57;
}

.uvq12-sh .tb i:nth-child(2) {
  background: #febc2e;
}

.uvq12-sh .tb i:nth-child(3) {
  background: #28c840;
}

.uvq12-sh .tb span {
