  color: #e6edf3;
  cursor: default;
}

.uvq12-sh .pa button:last-child:hover {
  background: none;
  text-decoration: none;
}

.uvq12-sh .cm {
  color: #e6edf3;
}

.uvq12-sh .cr {
  display: inline-block;
  width: .55em;
  height: 1.1em;
  vertical-align: -.2em;
  background: #e6edf3;
  animation: uvq12-sh-b 1s steps(1,end) infinite;
}

.uvq12-sh .ls {
  display: flex;
  flex-wrap: wrap;
  gap: .1em 1.1em;
  margin: .2em 0 0;
  padding: 0;
  list-style: none;
}

.uvq12-sh .ls li {
  animation: uvq12-sh calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1) both;
}

.uvq12-sh .ls button {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
