  padding: 0 .1em;
  border-radius: .2em;
  color: var(--c2);
  font-weight: 700;
}

.uvq12-sh .ls button:hover {
  background: color-mix(in srgb,var(--c2) 18%,transparent);
}

.uvq12-sh .ls span {
  color: #8b949e;
}

.uvq12-sh button:active {
  transform: translateY(1px);
}

.uvq12-sh button:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 1px;
}

@keyframes uvq12-sh {
  from {
    opacity: 0;
  }
}

@keyframes uvq12-sh-b {
  50% {
    opacity: 0;
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq12-sh,.uvq12-sh *,.uvq12-sh *::before,.uvq12-sh *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
