  const FS={"~":["code","docs","notes.txt"],"~/code":["web","app","scripts"],"~/code/web":["src","public","package.json"],"~/code/web/src":["components","styles","main.ts"],"~/code/web/src/components":["Button.tsx","Nav.tsx"],"~/code/web/src/styles":["base.css"],"~/code/web/public":["logo.svg"],"~/code/app":["ios","android"],"~/code/app/ios":["App.swift"],"~/code/app/android":["Main.kt"],"~/code/scripts":["deploy.sh"],"~/docs":["cv.pdf","ideas.md"]};
