const mk=(t,c)=>{const b=document.createElement("button");b.type="button";b.textContent=t;if(c)b.addEventListener("click",c);return b};
const render=()=>{pa.textContent="";const parts=cwd.split("/");parts.forEach((p,i)=>{if(i)pa.append("/");const b=mk(p,i<parts.length-1?()=>cd(parts.slice(0,i+1).join("/")):null);if(i===parts.length-1)b.setAttribute("aria-current","location");pa.append(b)});ls.textContent="";(FS[cwd]||[]).forEach((n,i)=>{const li=document.createElement("li");li.style.animationDelay=(i*40)+"ms";if(FS[cwd+"/"+n])li.append(mk(n+"/",()=>cd(cwd+"/"+n)));else{const s=document.createElement("span");s.textContent=n;li.append(s)}ls.append(li)})};
const rel=to=>{if(to.startsWith(cwd+"/"))return to.slice(cwd.length+1);const up=cwd.split("/").length-to.split("/").length;return Array(up).fill("..").join("/")};
const cd=to=>{if(busy||to===cwd)return;busy=true;const c="cd "+rel(to);let i=0;const back=el.contains(document.activeElement);const tick=()=>{cm.textContent=c.slice(0,++i);if(i<c.length)tms.push(setTimeout(tick,(38+Math.random()*40)/K()));else tms.push(setTimeout(()=>{const h=document.createElement("div");h.textContent="ana@mac:"+cwd+"$ "+c;hs.append(h);while(hs.children.length>2)hs.firstChild.remove();cm.textContent="";cwd=to;render();busy=false;if(back){const f=ls.querySelector("button")||pa.querySelector("button");if(f)f.focus()}},160/K()))};tick()};
el.addEventListener("keydown",e=>{if(e.key==="Backspace"&&cwd!=="~"){e.preventDefault();cd(cwd.split("/").slice(0,-1).join("/"))}});
render();return()=>tms.forEach(clearTimeout)
});

