.uvq12-rw {
  --c1: #22c55e;
  --c2: #f8fafc;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq12-rw {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  width: 22em;
  --p: 3;
}

.uvq12-rw .rd {
  display: flex;
  justify-content: center;
  align-items: baseline;
  gap: .35em;
  margin: 0 0 .6em;
  font-size: .85em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uvq12-rw .rd b {
  min-width: 1.2em;
  font-size: 2em;
  font-weight: 800;
  text-align: center;
  color: var(--fg);
  font-variant-numeric: tabular-nums;
}

.uvq12-rw .cs {
  display: flex;
  align-items: center;
  gap: .5em;
}

.uvq12-rw .pv,.uvq12-rw .nx {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  flex: none;
  display: grid;
  place-items: center;
  width: 2.2em;
  height: 2.2em;
  border-radius: 50%;
  background: color-mix(in srgb,var(--fg) 2%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 9%,transparent),0 1.4em 2.8em -1.4em rgba(0,0,0,.45);
  transition: transform calc(0.2s / var(--k)) cubic-bezier(.34,1.56,.64,1),opacity calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq12-rw .pv svg,.uvq12-rw .nx svg {
  width: 1em;
  height: 1em;
}

.uvq12-rw .pv:active,.uvq12-rw .nx:active {
  transform: scale(.88);
}

.uvq12-rw .pv:disabled,.uvq12-rw .nx:disabled {
  opacity: .35;
  cursor: default;
}

.uvq12-rw button:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 2px;
}

.uvq12-rw .rn {
  position: relative;
  flex: 1;
  height: 5.6em;
  border-radius: .35em;
  overflow: hidden;
  background: radial-gradient(circle,#fde68a .12em,transparent .17em) 0 .3em/1.05em .6em repeat-x,radial-gradient(circle,#fde68a .12em,transparent .17em) 0 calc(100% - .3em)/1.05em .6em repeat-x,repeating-radial-gradient(circle at 30% 40%,rgba(255,255,255,.025) 0 1px,transparent 1px 4px),linear-gradient(180deg,#3a3c42,#2a2c31);
  box-shadow: 0 .8em 1.6em -.9em rgba(0,0,0,.6);
}

.uvq12-rw .rn::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: .7em;
  bottom: .7em;
  border-top: 2px solid rgba(248,250,252,.75);
  border-bottom: 2px solid rgba(248,250,252,.75);
}

.uvq12-rw .rn::after {
  content: "";
  position: absolute;
  left: .3em;
  top: 1.05em;
  bottom: 1.05em;
  width: .6em;
  background: repeating-linear-gradient(180deg,rgba(248,250,252,.8) 0 .22em,transparent .22em .42em);
}

.uvq12-rw .cl {
  position: absolute;
  left: 1.2em;
  right: .6em;
  top: 50%;
  height: .14em;
  margin-top: -.07em;
  background: repeating-linear-gradient(90deg,rgba(248,250,252,.8) 0 .8em,transparent .8em 1.45em);
}

.uvq12-rw .ns {
  position: absolute;
  left: 1.1em;
  right: .3em;
  bottom: .85em;
  display: grid;
  grid-template-columns: repeat(8,1fr);
}

.uvq12-rw .ns button {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  padding: .15em 0;
  border-radius: .3em;
  font: 800 .72em/1 ui-monospace,"SF Mono",Menlo,Consolas,monospace;
  letter-spacing: .04em;
  color: rgba(248,250,252,.5);
  transition: color calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1),transform calc(0.2s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq12-rw .ns button:hover {
  color: #fff;
}

.uvq12-rw .ns button:active {
  transform: scale(.9);
}

.uvq12-rw .ns button[aria-current] {
  color: #fff;
  text-shadow: 0 0 .5em var(--c1);
}

.uvq12-rw .ns button:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 1px;
}

.uvq12-rw .pl,.uvq12-rw .gl,.uvq12-rw .rb {
  position: absolute;
  left: calc(1.1em + (100% - 1.4em) * (var(--p) - .5) / 8);
}

.uvq12-rw .pl {
  z-index: 1;
  top: 50%;
  width: 2em;
  height: 2em;
  margin: -1em 0 0 -1em;
  fill: var(--c2);
  filter: drop-shadow(.25em .35em .1em rgba(0,0,0,.45));
  transform: rotate(90deg);
  transition: left calc(1s / var(--k)) cubic-bezier(.22,1,.36,1),transform calc(0.35s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq12-rw.bk .pl {
  transform: rotate(-90deg);
}

.uvq12-rw .gl {
  top: .95em;
  bottom: .95em;
  width: .3em;
  margin-left: -1.5em;
  background: radial-gradient(circle,var(--c1) .1em,transparent .15em) 0 0/.3em .42em repeat-y;
  filter: drop-shadow(0 0 .25em var(--c1));
  transition: left calc(1s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uvq12-rw .rb {
  top: 50%;
  width: .4em;
  height: .4em;
  margin: -.2em 0 0 -.2em;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 0 .5em .15em #fff;
  opacity: 0;
  animation: uvq12-rw calc(1.3s / var(--k)) linear infinite;
}

@keyframes uvq12-rw {
  0% {
    left: .6em;
    opacity: 0;
  }
  10% {
    opacity: 1;
  }
  80% {
    opacity: .9;
  }
  100% {
    left: calc(1.1em + (100% - 1.4em) * (var(--p) - .5) / 8 - 1.6em);
    opacity: 0;
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq12-rw .rb {
    display: none;
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq12-rw,.uvq12-rw *,.uvq12-rw *::before,.uvq12-rw *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

