.uvq12-cw {
  --c1: #2563eb;
  --c2: #ecebe5;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq12-cw {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  width: 21em;
  padding: 1.1em 1em .8em;
  border-radius: 1.6em;
  color: #44403c;
  background: linear-gradient(180deg,color-mix(in srgb,var(--c2) 70%,#fff),var(--c2) 60%,color-mix(in srgb,var(--c2) 88%,#78716c));
  box-shadow: inset 0 1px 0 rgba(255,255,255,.8),inset 0 -.3em .6em rgba(0,0,0,.06),0 1.2em 2.4em -1.2em rgba(0,0,0,.45);
}

.uvq12-cw .wl {
  display: grid;
  grid-template-columns: repeat(4,1fr);
  gap: .4em;
}

.uvq12-cw [role="tab"] {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .6em;
  padding: .3em 0;
  border-radius: 1em;
}

.uvq12-cw .wn {
  position: relative;
  display: block;
  width: 3.5em;
  height: 4.6em;
  border-radius: 1.75em;
  overflow: hidden;
  box-shadow: 0 0 0 .32em color-mix(in srgb,var(--c2) 60%,#fff),0 0 0 .42em color-mix(in srgb,var(--c2) 80%,#57534e),inset 0 .25em .6em rgba(0,0,0,.4);
}

.uvq12-cw .vw {
  position: absolute;
  inset: 0;
  background-size: 200% 100%,100% 100%;
  animation: uvq12-cw-d 14s linear infinite;
}

.uvq12-cw .v0 {
  background-image: radial-gradient(ellipse 30% 9% at 30% 62%,#fff 60%,transparent 62%),linear-gradient(180deg,#3b82f6,#93c5fd 60%,#e0f2fe);
}

.uvq12-cw .v1 {
  background-image: radial-gradient(ellipse 34% 7% at 40% 70%,#fde68a 55%,transparent 60%),linear-gradient(180deg,#7c2d12,#f97316 45%,#fcd34d 75%,#fef3c7);
}

.uvq12-cw .v2 {
  background-image: radial-gradient(circle at 20% 30%,#fff .06em,transparent .1em),radial-gradient(circle at 70% 18%,#fff .05em,transparent .09em),radial-gradient(circle at 55% 52%,#fff .04em,transparent .08em),linear-gradient(180deg,#020617,#1e1b4b 70%,#312e81);
}

.uvq12-cw .v3 {
  background-image: radial-gradient(ellipse 18% 4% at 60% 60%,#fff 40%,transparent 60%),linear-gradient(180deg,#7dd3fc 0 52%,#0284c7 52%,#075985);
}

.uvq12-cw .sh {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(180deg,transparent 0 .45em,rgba(0,0,0,.035) .45em calc(.45em + 1px)),linear-gradient(180deg,#f7f6f2,#dedbd3);
  box-shadow: inset 0 -.4em 0 -.1em #cbc7bd,0 .2em .4em rgba(0,0,0,.25);
  transition: transform calc(0.7s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uvq12-cw .sh::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: .45em;
  width: 1.2em;
  height: .28em;
  margin-left: -.6em;
  border-radius: 1em;
  background: #b9b4a9;
}

.uvq12-cw [role="tab"]:not([aria-selected="true"]):hover .sh {
  transform: translateY(-16%);
}

.uvq12-cw [aria-selected="true"] .sh {
  transform: translateY(-86%);
}

.uvq12-cw [role="tab"]:active .wn {
  transform: scale(.97);
}

.uvq12-cw .lb {
  font-size: .72em;
  font-weight: 700;
  letter-spacing: .04em;
  color: #57534e;
  transition: color calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq12-cw [aria-selected="true"] .lb {
  color: var(--c1);
}

.uvq12-cw [role="tab"]:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 2px;
}

.uvq12-cw .bd {
  display: flex;
  align-items: center;
  gap: .6em;
  margin-top: .8em;
  padding: .6em .8em;
  border-radius: .8em;
  background: rgba(0,0,0,.05);
  box-shadow: inset 0 .1em .2em rgba(0,0,0,.08);
}

.uvq12-cw .lt {
  flex: none;
  width: .6em;
  height: .6em;
  border-radius: 50%;
  background: #fef9c3;
  box-shadow: 0 0 .6em #fde047,0 0 0 .15em #d6d3d1;
}

.uvq12-cw .pn {
  font-size: .8em;
  line-height: 1.4;
  animation: uvq12-cw calc(0.4s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq12-cw .pn[hidden] {
  display: none;
}

@keyframes uvq12-cw {
  from {
    opacity: 0;
    transform: translateY(.3em);
  }
