.uvq12-rv {
  --c1: #0ea5e9;
  --c2: #94a3b8;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq12-rv {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  display: flex;
  align-items: center;
  gap: 1.1em;
  width: 22em;
}

.uvq12-rv .dr {
  position: relative;
  flex: none;
  width: 11.5em;
  height: 11.5em;
  touch-action: none;
  cursor: grab;
}

.uvq12-rv.drag .dr {
  cursor: grabbing;
}

.uvq12-rv svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
}

.uvq12-rv .fl {
  fill: color-mix(in srgb,var(--fg) 4%,var(--bg));
  stroke: color-mix(in srgb,var(--fg) 10%,transparent);
  stroke-width: 1;
}

.uvq12-rv .wl {
  fill: none;
  stroke: var(--c2);
  stroke-width: 7;
  stroke-linecap: round;
}

.uvq12-rv .mt {
  fill: color-mix(in srgb,var(--c1) 30%,transparent);
}

.uvq12-rv .ro path {
  stroke: color-mix(in srgb,var(--c1) 70%,transparent);
  stroke-width: 4;
  stroke-linecap: round;
  filter: drop-shadow(0 0 3px color-mix(in srgb,var(--c1) 50%,transparent));
}

.uvq12-rv .ro circle {
  fill: var(--c2);
  stroke: var(--bg);
  stroke-width: 2;
}

.uvq12-rv [role="tab"] {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: absolute;
  transform: translate(-50%,-50%);
  padding: .3em .5em;
  border-radius: .6em;
  font-size: .72em;
  font-weight: 650;
  white-space: nowrap;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
  transition: color calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1),background calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq12-rv [role="tab"]:hover {
  color: var(--fg);
  background: color-mix(in srgb,var(--fg) 6%,transparent);
}

.uvq12-rv [role="tab"][aria-selected="true"] {
  color: #fff;
  background: var(--c1);
}

.uvq12-rv [role="tab"]:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 2px;
}

.uvq12-rv .in {
  flex: 1;
  min-width: 0;
}

.uvq12-rv .pn {
  display: flex;
  flex-direction: column;
  gap: .3em;
  animation: uvq12-rv calc(0.4s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uvq12-rv .pn[hidden] {
  display: none;
}

.uvq12-rv .pn b {
  font-size: 1.25em;
  letter-spacing: -.02em;
}

.uvq12-rv .pn span {
  font-size: .8em;
  line-height: 1.45;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

@keyframes uvq12-rv {
  from {
    opacity: 0;
    transform: translateY(.4em);
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq12-rv,.uvq12-rv *,.uvq12-rv *::before,.uvq12-rv *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

