css:
.uvq12-cr {
  --c1: #f5b301;
  --c2: #a8a29e;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq12-cr {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  width: 22em;
  height: 14.2em;
  --i: 0;
  --h: 1.9em;
}

.uvq12-cr .ms,.uvq12-cr .jb {
  position: absolute;
  background: repeating-linear-gradient(45deg,transparent 0 .42em,var(--c1) .42em .56em),repeating-linear-gradient(-45deg,transparent 0 .42em,var(--c1) .42em .56em);
}

.uvq12-cr .ms {
  left: 1.3em;
  top: 1.6em;
  bottom: 3.2em;
  width: 1.1em;
  border-left: .16em solid var(--c1);
  border-right: .16em solid var(--c1);
}

.uvq12-cr .ms::before {
  content: "";
  position: absolute;
  left: -.16em;
  right: -.16em;
  top: -1.4em;
  height: 1.4em;
  clip-path: polygon(50% 0,100% 100%,0 100%);
  background: var(--c1);
}

.uvq12-cr .jb {
  left: 0;
  right: .3em;
  top: 1.6em;
  height: .95em;
  border-top: .16em solid var(--c1);
  border-bottom: .16em solid var(--c1);
}

.uvq12-cr .cw {
  position: absolute;
  left: .1em;
  top: 2.7em;
  width: 1.1em;
  height: 1.3em;
  border-radius: .15em;
  background: repeating-linear-gradient(180deg,#78716c 0 .4em,#57534e .4em .45em);
}

.uvq12-cr .tr {
  position: absolute;
  z-index: 1;
  top: 2.55em;
  left: calc(3.6em + (100% - 4.3em) * (var(--i) + .5) / 4);
  width: 1.3em;
  height: .5em;
  margin-left: -.65em;
  border-radius: .12em;
  background: #3f3f46;
  transition: left calc(0.85s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uvq12-cr .cb {
  position: absolute;
  left: 50%;
  top: 100%;
  width: 2px;
  height: var(--h);
  margin-left: -1px;
  background: color-mix(in srgb,var(--fg) 70%,#3f3f46);
  transition: height calc(0.5s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq12-cr .cb svg {
  position: absolute;
  left: 50%;
  bottom: -.75em;
  width: 1em;
  height: 1em;
  margin-left: -.42em;
  fill: none;
  stroke: color-mix(in srgb,var(--fg) 70%,#3f3f46);
  stroke-width: 2.6;
  stroke-linecap: round;
}

.uvq12-cr .gd {
  position: absolute;
  left: 3.6em;
  right: .7em;
  bottom: 3.2em;
  display: grid;
  grid-template-columns: repeat(4,1fr);
  gap: .35em;
}

.uvq12-cr [role="tab"] {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  height: 2.5em;
  border-radius: .2em;
  translate: 0 0;
  transition: translate calc(0.5s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uvq12-cr [role="tab"].up {
  translate: 0 -3.1em;
}

.uvq12-cr .bk {
  position: relative;
  display: grid;
  place-items: center;
  height: 100%;
  border-radius: .2em;
  font-size: .68em;
  font-weight: 800;
  letter-spacing: .03em;
  color: #292524;
  background: radial-gradient(circle at 30% 40%,rgba(0,0,0,.06) 1px,transparent 1.5px) 0 0/.5em .5em,linear-gradient(180deg,color-mix(in srgb,var(--c2) 70%,#fff),var(--c2));
  box-shadow: inset 0 -.25em 0 rgba(0,0,0,.12),0 .2em .3em rgba(0,0,0,.3);
  transform-origin: 50% -2em;
}

.uvq12-cr .bk::before {
  content: "";
  position: absolute;
  left: 30%;
  right: 30%;
  top: -.5em;
  height: .5em;
  border: 2px solid #57534e;
  border-bottom: 0;
  border-radius: .4em .4em 0 0;
  opacity: .7;
}

.uvq12-cr .up .bk {
  animation: uvq12-cr 2.6s ease-in-out infinite alternate;
  color: #1c1917;
  box-shadow: inset 0 -.25em 0 rgba(0,0,0,.12),0 0 0 .14em var(--c1),0 1.4em 1em -1em rgba(0,0,0,.35);
}

.uvq12-cr [role="tab"]:hover .bk {
  filter: brightness(1.05);
}

.uvq12-cr [role="tab"]:active .bk {
  transform: scale(.96);
}

.uvq12-cr [role="tab"]:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 2px;
}

.uvq12-cr .gr {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 2.75em;
  height: .45em;
  border-top: 2px solid color-mix(in srgb,var(--fg) 35%,transparent);
  background: repeating-linear-gradient(-45deg,color-mix(in srgb,var(--fg) 12%,transparent) 0 2px,transparent 2px .4em);
}

.uvq12-cr .pn {
  position: absolute;
  left: 0;
  right: 0;
  bottom: .5em;
  text-align: center;
  font-size: .8em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
  animation: uvq12-cr-in calc(0.4s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq12-cr .pn[hidden] {
  display: none;
}

@keyframes uvq12-cr {
  from {
    transform: rotate(-2.5deg);
  }
  to {
    transform: rotate(2.5deg);
  }
}

@keyframes uvq12-cr-in {
  from {
    opacity: 0;
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq12-cr,.uvq12-cr *,.uvq12-cr *::before,.uvq12-cr *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

